function AddTerritoryModal({ onClose, onSubmit }) {
  const [name, setName] = useState('');
  const [owner, setOwner] = useState('');
  const [coords, setCoords] = useState('');

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 60,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: '100%', maxWidth: 448, background: 'var(--surface)', borderTopLeftRadius: 22, borderTopRightRadius: 22,
          border: '1px solid var(--border)', borderBottom: 'none', padding: 18, maxHeight: '80vh', overflowY: 'auto',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
          <div className="atlas-display" style={{ fontSize: 16, fontWeight: 700 }}>Добавить территорию</div>
          <button onClick={onClose} className="press" style={iconBtn('var(--surface-2)', 'var(--text-muted)')}><X size={16} /></button>
        </div>

        <Field label="Название территории" value={name} onChange={(e) => setName(e.target.value)} placeholder="Например, Айсбург" />
        <Field label="Ник и/или юзернейм владельца" value={owner} onChange={(e) => setOwner(e.target.value)} placeholder="Ник в Minecraft, @username в Telegram" />
        <Field label="Координаты" value={coords} onChange={(e) => setCoords(e.target.value)} placeholder="X 120 / Z −340" />

        <button
          onClick={() => onSubmit({ name: name.trim(), owner: owner.trim(), coords: coords.trim() })}
          disabled={!name.trim() || !owner.trim()}
          className="press"
          style={{
            width: '100%', marginTop: 4, padding: '12px 0', borderRadius: 12, border: 'none',
            cursor: name.trim() && owner.trim() ? 'pointer' : 'not-allowed',
            opacity: name.trim() && owner.trim() ? 1 : 0.5,
            background: 'var(--indigo)', color: '#fff', fontWeight: 700, fontSize: 14,
          }}
        >
          Отправить на подтверждение
        </button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Profile screen
// ---------------------------------------------------------------------------
function ProfileScreen({ profile, claimNickname, isInspector, tgUser }) {
  const [draft, setDraft] = useState(profile.nickname || '');
  const [error, setError] = useState('');

  function submit() {
    const res = claimNickname(draft);
    setError(res.ok ? '' : res.message);
  }

  return (
    <div style={{ padding: '18px 16px 40px', minHeight: '60vh' }}>
      <div className="atlas-display" style={{ fontSize: 22, fontWeight: 700, marginBottom: 4 }}>Профиль</div>
      <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 20 }}>
        Ник нужен, чтобы выставлять оценки и оставлять отзывы под своим именем.
      </div>

      <div style={{
        background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 16, marginBottom: 12,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
          <AvatarHead nickname={profile.status === 'verified' ? profile.nickname : null} size={46} />
          <div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{profile.nickname || 'Ник не указан'}</div>
            {isInspector ? (
              <div style={{ fontSize: 11.5, color: 'var(--gold)', display: 'flex', alignItems: 'center', gap: 4, fontWeight: 700 }}>
                <ShieldCheck size={12} /> Инспектор
              </div>
            ) : profile.status === 'verified' ? (
              <div style={{ fontSize: 11.5, color: 'var(--emerald)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <ShieldCheck size={12} /> Ник подтверждён
              </div>
            ) : profile.status === 'pending' ? (
              <div style={{ fontSize: 11.5, color: 'var(--gold)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <Clock size={12} /> Ожидает подтверждения инспектора
              </div>
            ) : (
              <div style={{ fontSize: 11.5, color: 'var(--text-muted)' }}>Ник в Minecraft</div>
            )}
          </div>
        </div>

        <div style={{ fontSize: 11.5, color: 'var(--text-muted)', marginBottom: 10 }}>
          Telegram: {tgUser ? `@${tgUser.username || '—'} · id ${tgUser.id}` : 'не определён (открыто вне Telegram)'}
        </div>

        {!isInspector && (
          <>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                placeholder="Ваш ник в Minecraft"
                style={{
                  flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
                  padding: '10px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
                }}
              />
              <button onClick={submit} className="press" style={iconBtn('var(--indigo)', '#fff', true)}>
                <Pencil size={15} />
              </button>
            </div>
            {error && <div style={{ fontSize: 12, color: 'var(--red)', marginTop: 8 }}>{error}</div>}
          </>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Home screen — Multi-Punk
// ---------------------------------------------------------------------------
function HomeScreen({ territories, onSelect, onAddTerritory }) {
  const [mode, setMode] = useState('map');
  const [sortBy, setSortBy] = useState('curator'); // 'curator' | 'community'
  const sortedList = [...territories].sort((a, b) => b[sortBy] - a[sortBy]);

  return (
    <div style={{ paddingBottom: 90 }}>
      <div style={{ padding: '18px 16px 10px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
        <div>
          <div className="atlas-display" style={{ fontSize: 22, fontWeight: 700, letterSpacing: -0.3 }}>
            Multi-Punk
          </div>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', marginTop: 2 }}>
            {territories.length} мест
          </div>
        </div>
        <button
          onClick={onAddTerritory}
          className="press"
          style={{
            display: 'flex', alignItems: 'center', gap: 6, padding: '9px 14px', borderRadius: 999,
            border: 'none', cursor: 'pointer', background: 'var(--indigo)', color: '#fff', fontWeight: 700, fontSize: 13,
            flexShrink: 0, marginTop: 2,
          }}
        >
          <Plus size={15} /> Добавить
        </button>
      </div>

      <div style={{ padding: '4px 16px 14px' }}>
        <Segmented
          value={mode}
          onChange={setMode}
          options={[
            { value: 'map', label: 'Карта', icon: <MapIcon size={14} /> },
            { value: 'list', label: 'Рейтинг', icon: <ListIcon size={14} /> },
          ]}
        />
      </div>

      {mode === 'map' ? (
        <div style={{ padding: '0 16px' }}>
          <div
            style={{
              position: 'relative', width: '100%', aspectRatio: '1 / 1', borderRadius: 20,
              border: '1px solid var(--border)', overflow: 'hidden',
              backgroundImage: `url(${MAP_IMAGE})`, backgroundSize: 'cover', backgroundPosition: 'center',
            }}
          >
            <div style={{
              position: 'absolute', inset: 0,
              background: 'linear-gradient(180deg, rgba(11,13,16,0.15), rgba(11,13,16,0.05) 30%, rgba(11,13,16,0.25))',
            }} />

            {territories.map((t) => (
              <button
                key={t.id}
                onClick={() => onSelect(t.id)}
                className="press"
                style={{
                  position: 'absolute', left: `${t.x}%`, top: `${t.y}%`, transform: 'translate(-50%,-50%)',
                  border: 'none', background: 'transparent', cursor: 'pointer', padding: 8,
                }}
                title={t.name}
              >
                <span style={{ position: 'relative', display: 'block', width: 14, height: 14 }}>
                  <span className="pin-pulse" style={{
                    position: 'absolute', inset: 0, borderRadius: '50%', background: t.accent,
                  }} />
                  <span style={{
                    position: 'absolute', inset: 0, borderRadius: '50%', background: t.accent,
                    border: '2px solid var(--bg)',
                  }} />
                </span>
              </button>
            ))}
          </div>
          {territories.length === 0 && (
            <div style={{ textAlign: 'center', fontSize: 12.5, color: 'var(--text-muted)', marginTop: 12 }}>
              Отмеченных территорий пока нет — добавьте первую.
            </div>
          )}
        </div>
      ) : (
        <div style={{ padding: '0 16px' }}>
          <div style={{ marginBottom: 10 }}>
            <Segmented
              value={sortBy}
              onChange={setSortBy}
              options={[
                { value: 'curator', label: 'По инспектору' },
                { value: 'community', label: 'По игрокам' },
              ]}
            />
          </div>
          {sortedList.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px 16px', color: 'var(--text-muted)', fontSize: 13 }}>
              Городов пока нет — станьте первым, кто добавит свой.
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {sortedList.map((t, i) => (
                <button
                  key={t.id}
                  onClick={() => onSelect(t.id)}
                  className="press"
                  style={{
                    display: 'flex', alignItems: 'center', gap: 12, textAlign: 'left',
                    background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16,
                    padding: 10, cursor: 'pointer', color: 'var(--text)',
                  }}
                >
                  <span className="atlas-display" style={{ width: 20, fontSize: 13, color: 'var(--text-muted)', fontWeight: 600 }}>
                    {i + 1}
                  </span>
                  <div style={{
                    width: 46, height: 46, borderRadius: 12, flexShrink: 0,
                    background: `linear-gradient(135deg, ${t.accent}55, ${t.accent}15)`,
                    border: `1px solid ${t.accent}55`,
                  }} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div className="atlas-display" style={{ fontSize: 14, fontWeight: 600 }}>{t.name}</div>
                    <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{t.owner} · {t.votes} оценок</div>
                  </div>
                  {sortBy === 'curator' ? (
                    <ScoreBadge type="curator" value={t.curator} size="lg" />
                  ) : (
                    <ScoreBadge type="community" value={t.community} size="lg" />
                  )}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Territory detail
// ---------------------------------------------------------------------------
function TerritoryDetail({ base, onBack, profile, onGoToProfile }) {
  const [t, setT] = useState(base);

  const hasNickname = profile.status === 'pending' || profile.status === 'verified';
  const isOwner = profile.status === 'verified' && profile.nickname.trim().toLowerCase() === t.owner.trim().toLowerCase();
  const isResident = !isOwner && hasNickname && t.residents.some((r) => r.trim().toLowerCase() === profile.nickname.trim().toLowerCase());

  const [ratedToday, setRatedToday] = useState(false);
  const [myRating, setMyRating] = useState({ integrity: 3, comfort: 3, atmosphere: 3, detail: 3 });
  const [reacted, setReacted] = useState({});
  const [newComment, setNewComment] = useState('');
  const [showResidents, setShowResidents] = useState(false);
  const [newResident, setNewResident] = useState('');
  const [toast, setToast] = useState(null);
  const [curatorRequested, setCuratorRequested] = useState(false);
  const [lightbox, setLightbox] = useState(null); // { shot, mode: 'view' | 'moderate' }
  const fileInputRef = useRef(null);

  function flash(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 2200);
  }

  function saveRating() {
    setRatedToday(true);
    flash('Оценка сохранена — обновится в общем рейтинге сегодня');
  }

  function react(reviewId, kind) {
    setReacted((prev) => {
      const current = prev[reviewId];
      if (kind === 'report') {
        flash('Жалоба отправлена инспектору');
        return { ...prev, [reviewId]: current === 'reported' ? current : 'reported' };
      }
      const already = current === kind;
      setT((prevT) => ({
        ...prevT,
        reviews: prevT.reviews.map((r) => {
          if (r.id !== reviewId) return r;
          const likes = r.likes + (kind === 'like' ? (already ? -1 : current === 'dislike' ? 1 : 1) : current === 'like' ? -1 : 0);
          const dislikes = r.dislikes + (kind === 'dislike' ? (already ? -1 : current === 'like' ? 1 : 1) : current === 'dislike' ? -1 : 0);
          return { ...r, likes, dislikes };
        }),
      }));
      return { ...prev, [reviewId]: already ? null : kind };
    });
  }

  function addComment() {
    if (!newComment.trim() || !hasNickname) return;
    setT((prev) => ({
      ...prev,
      reviews: [{ id: `r${Date.now()}`, author: profile.nickname, text: newComment.trim(), likes: 0, dislikes: 0, reply: null }, ...prev.reviews],
    }));
    setNewComment('');
    flash('Отзыв опубликован');
  }

  function reply(reviewId, text) {
    setT((prev) => ({ ...prev, reviews: prev.reviews.map((r) => (r.id === reviewId ? { ...r, reply: text } : r)) }));
  }

  function moderateShot(id, approve) {
    setT((prev) => ({
      ...prev,
      screenshots: prev.screenshots.map((s) => (s.id === id ? { ...s, status: approve ? 'approved' : 'rejected' } : s)),
    }));
    flash(approve ? 'Скрин добавлен в галерею' : 'Скрин перемещён в отклонённые');
    setLightbox(null);
  }

  function handleFilePicked(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file) return;
    const url = URL.createObjectURL(file);
    setT((prev) => ({
      ...prev,
      screenshots: [...prev.screenshots, { id: `s${Date.now()}`, author: profile.nickname || 'Гость', status: 'pending', url }],
    }));
    flash('Скрин отправлен на модерацию владельцу');
  }

  function addResident() {
    if (!newResident.trim()) return;
    setT((prev) => ({ ...prev, residents: [...prev.residents, newResident.trim()] }));
    setNewResident('');
  }

  function removeResident(name) {
    setT((prev) => ({ ...prev, residents: prev.residents.filter((r) => r !== name) }));
  }

  const approved = t.screenshots.filter((s) => s.status === 'approved');
  const pending = t.screenshots.filter((s) => s.status === 'pending');

  return (
    <div style={{ paddingBottom: 90, position: 'relative' }}>
      <div style={{
        position: 'relative', height: 150,
        background: `linear-gradient(160deg, ${t.accent}66, var(--surface) 85%)`,
      }}>
        <button
          onClick={onBack}
          className="press"
          style={{
            position: 'absolute', top: 14, left: 14, width: 34, height: 34, borderRadius: '50%',
            background: 'rgba(11,13,16,0.55)', border: '1px solid var(--border)', color: 'var(--text)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
          }}
        >
          <ChevronLeft size={18} />
        </button>
        <div style={{ position: 'absolute', bottom: 14, left: 16, right: 16 }}>
          <div className="atlas-display" style={{ fontSize: 24, fontWeight: 700 }}>{t.name}</div>
          <div style={{ fontSize: 13, color: 'rgba(237,238,242,0.75)' }}>
            Владелец — {t.owner}{t.coords ? <span style={{ color: 'rgba(237,238,242,0.5)' }}> · {t.coords}</span> : null}
          </div>
        </div>
      </div>

      <div style={{ padding: '14px 16px 0' }}>
        <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
          <ScoreBadge type="curator" value={t.curator} />
          <ScoreBadge type="community" value={t.community} />
        </div>

        <SectionTitle icon={<Camera size={15} />} title="Скрины" count={approved.length} />
        <div className="atlas-scroll" style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4, marginBottom: 6 }}>
          {approved.map((s) => (
            <ShotThumb key={s.id} shot={s} onOpen={() => setLightbox({ shot: s, mode: 'view' })} />
          ))}
          {!isOwner && (
            <>
              <input ref={fileInputRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={handleFilePicked} />
              <button
                onClick={() => fileInputRef.current && fileInputRef.current.click()}
                className="press"
                style={{
                  flexShrink: 0, width: 96, height: 68, borderRadius: 12, cursor: 'pointer',
                  border: '1px dashed var(--border)', background: 'transparent', color: 'var(--text-muted)',
                  display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 4, fontSize: 11,
                }}
              >
                <Plus size={16} /> Добавить
              </button>
            </>
          )}
        </div>

        <button
          onClick={() => setShowResidents(true)}
          className="press"
          style={{
            width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 14,
            padding: '12px 14px', margin: '14px 0', cursor: 'pointer', color: 'var(--text)',
          }}
        >
          <span style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 14, fontWeight: 600 }}>
            <Users size={16} color="var(--text-muted)" /> Жители
          </span>
          <span style={{ fontSize: 13, color: 'var(--text-muted)' }}>{t.residents.length} →</span>
        </button>

        {!isOwner && (
          <div style={{
            background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 14, marginBottom: 18,
          }}>
            <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 10 }}>Ваша оценка</div>
            {!hasNickname ? (
              <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                Укажите ник в{' '}
                <button onClick={onGoToProfile} className="press" style={{ background: 'none', border: 'none', color: 'var(--indigo)', cursor: 'pointer', padding: 0, fontSize: 13, fontWeight: 600 }}>
                  профиле
                </button>
                , чтобы оценивать города.
              </div>
            ) : isResident ? (
              <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                Вы житель этого города — оценивать его нельзя. Но скрин прислать можно 🙂
              </div>
            ) : ratedToday ? (
              <div style={{ fontSize: 13, color: 'var(--emerald)', display: 'flex', alignItems: 'center', gap: 6 }}>
                <Check size={15} /> Учтено. Следующее обновление — завтра.
              </div>
            ) : (
              <>
                {CRITERIA.map((c) => (
                  <div key={c.key} style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 4 }}>{c.label}</div>
                      <input
                        type="range" min="1" max="5" value={myRating[c.key]} className="slider-gold"
                        onChange={(e) => setMyRating((p) => ({ ...p, [c.key]: Number(e.target.value) }))}
                        style={{ width: '100%' }}
                      />
                    </div>
                    <div className="atlas-display" style={{ width: 20, textAlign: 'center', fontSize: 17, fontWeight: 700, color: 'var(--gold)' }}>
                      {myRating[c.key]}
                    </div>
                  </div>
                ))}
                <button
                  onClick={saveRating}
                  className="press"
                  style={{
                    width: '100%', marginTop: 4, padding: '11px 0', borderRadius: 12, border: 'none', cursor: 'pointer',
                    background: 'var(--gold)', color: '#1A1300', fontWeight: 700, fontSize: 14,
                  }}
                >
                  Сохранить оценку
                </button>
              </>
            )}
          </div>
        )}

        {isOwner && (
          <div style={{
            background: 'var(--indigo-soft)', border: '1px solid rgba(168,85,247,0.35)', borderRadius: 16, padding: 14, marginBottom: 18,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 700, marginBottom: 10, color: 'var(--indigo)' }}>
              <Sparkles size={15} /> Инструменты владельца
            </div>

            <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 6 }}>Скрины на проверке</div>
            {pending.length === 0 ? (
              <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>Новых скринов на проверке нет.</div>
            ) : pending.map((s) => (
              <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                <ShotThumb shot={s} onOpen={() => setLightbox({ shot: s, mode: 'moderate' })} />
                <div style={{ flex: 1, fontSize: 12, color: 'var(--text-muted)' }}>от {s.author}</div>
                <button onClick={() => moderateShot(s.id, true)} className="press" style={iconBtn('var(--emerald-soft)', 'var(--emerald)')}><Check size={15} /></button>
                <button onClick={() => moderateShot(s.id, false)} className="press" style={iconBtn('var(--red-soft)', 'var(--red)')}><X size={15} /></button>
              </div>
            ))}

            <button
              onClick={() => { setCuratorRequested(true); flash('Заявка отправлена инспектору'); }}
              className="press"
              disabled={curatorRequested}
              style={{
                width: '100%', marginTop: 6, padding: '11px 0', borderRadius: 12, border: '1px solid var(--indigo)', cursor: 'pointer',
                background: curatorRequested ? 'transparent' : 'var(--indigo)', color: curatorRequested ? 'var(--indigo)' : '#fff',
                fontWeight: 700, fontSize: 13,
              }}
            >
              {curatorRequested ? 'Заявка на переоценку отправлена' : 'Запросить оценку инспектора'}
            </button>
          </div>
        )}

        <SectionTitle icon={<MessageCircle size={15} />} title="Отзывы" count={t.reviews.length} />

        {!isOwner && (
          hasNickname ? (
            <div style={{ display: 'flex', gap: 8, marginBottom: 14 }}>
              <input
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="Оставить отзыв о городе…"
                style={{
                  flex: 1, background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12,
                  padding: '10px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
                }}
              />
              <button onClick={addComment} className="press" style={iconBtn('var(--surface)', 'var(--text)', true)}>
                <Send size={15} />
              </button>
            </div>
          ) : (
            <div style={{ fontSize: 12.5, color: 'var(--text-muted)', marginBottom: 14 }}>
              Укажите ник в{' '}
              <button onClick={onGoToProfile} className="press" style={{ background: 'none', border: 'none', color: 'var(--indigo)', cursor: 'pointer', padding: 0, fontSize: 12.5, fontWeight: 600 }}>
                профиле
              </button>
              , чтобы оставлять отзывы.
            </div>
          )
        )}

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 10 }}>
          {t.reviews.length === 0 && (
            <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Пока нет отзывов — будьте первым, кто оценит этот город.</div>
          )}
          {t.reviews.map((r) => (
            <div key={r.id} style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 14, padding: 12 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                <span style={{ fontSize: 13, fontWeight: 600 }}>{r.author}</span>
              </div>
              <div style={{ fontSize: 13, color: 'var(--text)', lineHeight: 1.4, marginBottom: 8 }}>{r.text}</div>

              {r.reply && (
                <div style={{
                  fontSize: 12, color: 'var(--text-muted)', background: 'var(--surface-2)', borderRadius: 10,
                  padding: '8px 10px', marginBottom: 8, borderLeft: '2px solid var(--indigo)',
                }}>
                  <b style={{ color: 'var(--indigo)' }}>{t.owner}: </b>{r.reply}
                </div>
              )}
              {isOwner && !r.reply && <ReplyBox onSend={(text) => reply(r.id, text)} />}

              <div style={{ display: 'flex', gap: 14, marginTop: 6 }}>
                <button onClick={() => react(r.id, 'like')} className="press" style={reactBtn(reacted[r.id] === 'like')}>
                  <ThumbsUp size={13} /> {r.likes}
                </button>
                <button onClick={() => react(r.id, 'dislike')} className="press" style={reactBtn(reacted[r.id] === 'dislike')}>
                  <ThumbsDown size={13} /> {r.dislikes}
                </button>
                <button onClick={() => react(r.id, 'report')} className="press" style={{ ...reactBtn(false), marginLeft: 'auto', color: reacted[r.id] === 'reported' ? 'var(--red)' : 'var(--text-muted)' }}>
                  <Flag size={13} /> {reacted[r.id] === 'reported' ? 'Отправлено' : 'Пожаловаться'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showResidents && (
        <ResidentsModal
          residents={t.residents}
          ownerName={t.owner}
          isOwner={isOwner}
          onClose={() => setShowResidents(false)}
          newResident={newResident}
          setNewResident={setNewResident}
          onAdd={addResident}
          onRemove={removeResident}
        />
      )}

      {lightbox && (
        <Lightbox
          shot={lightbox.shot}
          mode={lightbox.mode}
          onClose={() => setLightbox(null)}
          onApprove={() => moderateShot(lightbox.shot.id, true)}
          onReject={() => moderateShot(lightbox.shot.id, false)}
        />
      )}

      {toast && (
        <div style={{
          position: 'fixed', bottom: 96, left: '50%', transform: 'translateX(-50%)',
          background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 999,
          padding: '9px 16px', fontSize: 12.5, color: 'var(--text)', boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
          zIndex: 50, whiteSpace: 'nowrap',
        }}>
          {toast}
        </div>
      )}
    </div>
  );
}

function ReplyBox({ onSend }) {
  const [val, setVal] = useState('');
  return (
    <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
      <input
        value={val}
        onChange={(e) => setVal(e.target.value)}
        placeholder="Ответить как владелец…"
        style={{
          flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
          padding: '7px 10px', color: 'var(--text)', fontSize: 12.5, outline: 'none',
        }}
      />
      <button
        onClick={() => { if (val.trim()) { onSend(val.trim()); setVal(''); } }}
        className="press"
        style={{ ...iconBtn('var(--indigo-soft)', 'var(--indigo)'), width: 32, height: 32 }}
      >
        <Send size={13} />
      </button>
    </div>
  );
}

function ResidentsModal({ residents, ownerName, isOwner, onClose, newResident, setNewResident, onAdd, onRemove }) {
  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 60,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: '100%', maxWidth: 448, background: 'var(--surface)', borderTopLeftRadius: 22, borderTopRightRadius: 22,
          border: '1px solid var(--border)', borderBottom: 'none', padding: 18, maxHeight: '70vh', overflowY: 'auto',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
          <div className="atlas-display" style={{ fontSize: 16, fontWeight: 700 }}>Жители</div>
          <button onClick={onClose} className="press" style={iconBtn('var(--surface-2)', 'var(--text-muted)')}><X size={16} /></button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: isOwner ? 14 : 0 }}>
          {residents.length === 0 && <div style={{ fontSize: 12.5, color: 'var(--text-muted)' }}>Список жителей пуст.</div>}
          {residents.map((name) => {
            const canRemove = isOwner && name.trim().toLowerCase() !== ownerName.trim().toLowerCase();
            return (
              <div key={name} style={{
                display: 'flex', alignItems: 'center', gap: 10, background: 'var(--surface-2)', borderRadius: 12, padding: '9px 12px',
              }}>
                <User size={15} color="var(--text-muted)" />
                <span style={{ fontSize: 13.5, flex: 1 }}>{name}{name.trim().toLowerCase() === ownerName.trim().toLowerCase() ? ' · владелец' : ''}</span>
                {canRemove && (
                  <button onClick={() => onRemove(name)} className="press" style={{ background: 'transparent', border: 'none', color: 'var(--red)', cursor: 'pointer' }}>
                    <Trash2 size={14} />
                  </button>
                )}
              </div>
            );
          })}
        </div>

        {isOwner && (
          <div style={{ display: 'flex', gap: 8 }}>
            <input
              value={newResident}
              onChange={(e) => setNewResident(e.target.value)}
              placeholder="Ник игрока"
              style={{
                flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
                padding: '9px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
              }}
            />
            <button onClick={onAdd} className="press" style={iconBtn('var(--indigo)', '#fff', true)}>
              <UserPlus size={15} />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function BottomNav({ screen, onNavigate }) {
  const items = [
    { key: 'atlas', icon: MapIcon, label: 'Города' },
    { key: 'profile', icon: User, label: 'Профиль' },
  ];
  return (
    <div style={{ position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 40, display: 'flex', justifyContent: 'center' }}>
      <div style={{
        width: '100%', maxWidth: 448, display: 'flex', background: 'rgba(20,23,28,0.92)',
        backdropFilter: 'blur(10px)', borderTop: '1px solid var(--border)', padding: '10px 6px 14px',
      }}>
        {items.map((it) => {
          const active = it.key === screen;
          return (
            <button
              key={it.key}
              onClick={() => onNavigate(it.key)}
              className="press"
              style={{
                flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                color: active ? 'var(--indigo)' : 'var(--text-muted)', background: 'none', border: 'none', cursor: 'pointer',
              }}
            >
              <it.icon size={19} strokeWidth={active ? 2.4 : 2} />
              <span style={{ fontSize: 10.5, fontWeight: active ? 700 : 500 }}>{it.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Root
// ---------------------------------------------------------------------------
export default function CityRatingApp() {
  const tgUser = getTelegramUser();
  const isRealInspector = !!tgUser && (
    tgUser.id === INSPECTOR.id ||
    (tgUser.username && tgUser.username.toLowerCase() === INSPECTOR.username.toLowerCase())
  );

  const [screen, setScreen] = useState('atlas');
  const [selectedId, setSelectedId] = useState(null);
  const [territories, setTerritories] = useState(TERRITORIES);
  const [profile, setProfile] = useState(() =>
    isRealInspector ? { nickname: INSPECTOR.nickname, status: 'verified' } : { nickname: '', status: 'none' }
  );
  const [verifiedSet, setVerifiedSet] = useState(new Set([INSPECTOR.nickname.toLowerCase()]));
  const [showAddTerritory, setShowAddTerritory] = useState(false);
  const [homeToast, setHomeToast] = useState(null);

  const selected = territories.find((t) => t.id === selectedId);

  function navigate(key) {
    setScreen(key);
    if (key === 'profile') setSelectedId(null);
  }

  function claimNickname(raw) {
    const nick = (raw || '').trim();
    if (!nick) return { ok: false, message: 'Введите ник.' };
    const lower = nick.toLowerCase();
    const ownedByOther = verifiedSet.has(lower) && lower !== profile.nickname.trim().toLowerCase();
    if (ownedByOther) return { ok: false, message: 'Этот ник уже подтверждён за другим аккаунтом.' };
    setProfile({ nickname: nick, status: 'pending' });
    return { ok: true };
  }

  function submitTerritoryRequest(data) {
    setShowAddTerritory(false);
    setHomeToast('Заявка отправлена инспектору на подтверждение');
    setTimeout(() => setHomeToast(null), 2600);
  }

  return (
    <div className="atlas-root" style={{ minHeight: '100vh', width: '100%' }}>
      <FontsAndTheme />
      <div style={{ maxWidth: 448, margin: '0 auto', position: 'relative' }}>
        {screen === 'profile' ? (
          <ProfileScreen profile={profile} claimNickname={claimNickname} isInspector={isRealInspector} tgUser={tgUser} />
        ) : selected ? (
          <TerritoryDetail
            base={selected}
            onBack={() => setSelectedId(null)}
            profile={profile}
            onGoToProfile={() => navigate('profile')}
          />
        ) : (
          <HomeScreen territories={territories} onSelect={setSelectedId} onAddTerritory={() => setShowAddTerritory(true)} />
        )}
        <BottomNav screen={screen} onNavigate={navigate} />

        {showAddTerritory && (
          <AddTerritoryModal onClose={() => setShowAddTerritory(false)} onSubmit={submitTerritoryRequest} />
        )}

        {homeToast && (
          <div style={{
            position: 'fixed', bottom: 96, left: '50%', transform: 'translateX(-50%)',
            background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 999,
            padding: '9px 16px', fontSize: 12.5, color: 'var(--text)', boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
            zIndex: 90, whiteSpace: 'nowrap',
          }}>
            {homeToast}
          </div>
        )}
      </div>
    </div>
  );
}
